#define GIANT_FX_CAPACITY 192
typedef struct{float x,y,vx,vy,age,life,size;float originX,originY;int kind,cell,clip,ownerIndex,ownerForm,surface,sourceMask,sourceU,sourceV;} GiantFX;
static GiantFX giantFX[GIANT_FX_CAPACITY];static int giantFXHead,giantFXSerial;static int gfxOwner=-1,gfxForm,gfxSurface,gfxMask,gfxU,gfxV;static float gfxOriginX,gfxOriginY;
void pc_giant_reset(void){memset(giantFX,0,sizeof(giantFX));giantFXHead=giantFXSerial=0;gfxOwner=-1;gfxSurface=0;}
static void giant_fx_emit(float x,float y,float vx,float vy,float life,float size,int kind,int cell){GiantFX*p=giantFX+giantFXHead;giantFXHead=(giantFXHead+1)%GIANT_FX_CAPACITY;float speed=reducedMotion?.55f:1;*p=(GiantFX){x,y,vx*speed,vy*speed,0,life,size,gfxOriginX,gfxOriginY,kind,cell,ex.giant.archetype==4,gfxOwner,gfxForm,gfxSurface,gfxMask,gfxU,gfxV};giantFXSerial++;}
void pc_giant_damage(void){Giant*b=&ex.giant;if(!g.fx||!b->active||b->timer%6)return;int limit=reducedMotion||quality==0?1:quality==1?2:4,emitted=0,start=b->timer/6%9;float scale=giant_world_scale();for(int n=0;n<9&&emitted<limit;n++){int i=(start+n)%9;GiantPart*p=b->parts+i;if(!giant_part_authored(i)||p->maxHp<=0||(b->archetype==4&&(i!=6||!p->visible))||(b->archetype!=4&&!giant_part_in_view(i)))continue;float damage=1-p->hp/(float)p->maxHp;if(i==6)damage=fmaxf(damage,giant_damage_fraction()*.9f);if(damage<(b->archetype==4?.015f:.12f))continue;int cadence=damage<.12f?24:damage<.35f?12:6;if(b->timer%cadence)continue;float x,y;int surface,mask,u,v;if(!giant_fx_anchor(i,&x,&y,&surface,&mask,&u,&v))continue;gfxOwner=i;gfxForm=b->form;gfxSurface=surface;gfxMask=mask;gfxU=u;gfxV=v;gfxOriginX=x;gfxOriginY=y;float dx=(p->x-b->previousPartX[i])*18,dy=(p->y-b->previousPartY[i])*18;emitted++;int organic=b->archetype==1||b->archetype==4;if(organic){int kind=b->archetype==1&&(i==6||i>=7)?3:4;giant_fx_emit(x,y,dx+(frand()-.5f)*12,dy+10,1.0f+frand()*.5f,(4+8*damage)*scale,kind,3);if(damage>=.35f)giant_fx_emit(x,y,dx*.4f,dy*.4f-8,2,18*scale,kind+2,7);}else{if(damage>=.25f)giant_fx_emit(x,y,dx*.35f+(frand()-.5f)*8,dy*.35f-11,2.2f+frand()*.5f,(24+frand()*8)*scale,0,4+(b->timer/6+i)%2);if(damage>=.6f)giant_fx_emit(x,y,dx*.25f,dy*.25f-3,.55f,(18+frand()*4)*scale,1,(b->timer/6+i)%4);if(b->timer%12==0)giant_fx_emit(x,y,dx+(frand()-.5f)*35,dy-25,.4f,11*scale,2,6);}}}
static void giant_fx_step(float dt){if(dt<=0)return;for(int i=0;i<GIANT_FX_CAPACITY;i++){GiantFX*p=giantFX+i;if(p->life<=0)continue;p->age+=dt;if(p->age>=p->life){p->life=0;continue;}float gravity=p->kind==3||p->kind==4?35:0;p->x+=p->vx*dt;p->y+=p->vy*dt+.5f*gravity*dt*dt;p->vy+=gravity*dt;}}
